"""Embedded, dependency-free browser interface for live capture and knowledge retrieval."""

PAGE = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>NoteTaker / Knowledge Capture</title>
<style>
:root{--ink:#18231f;--muted:#6e7c76;--paper:#f4f1e9;--card:#fffdf8;--line:#d9d7ce;--accent:#d85f3d;--green:#305d4d;--warn:#9b661e;--shadow:0 18px 55px #1c342415}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.6 Inter,ui-sans-serif,system-ui,sans-serif}button,input{font:inherit}button{cursor:pointer;border:0}.shell{max-width:1440px;margin:auto;padding:24px 28px 70px}.top{display:flex;align-items:flex-start;gap:24px;border-bottom:1px solid var(--line);padding-bottom:20px}.mark{font:700 12px ui-monospace,monospace;letter-spacing:.18em;color:var(--accent)}h1{margin:5px 0 0;font:700 clamp(32px,5vw,66px)/.95 Georgia,serif;letter-spacing:-.05em}.subtitle{max-width:480px;margin:7px 0 0;color:var(--muted)}.top .grow{flex:1}.pill{border:1px solid var(--line);border-radius:999px;padding:7px 12px;color:var(--muted);font:12px ui-monospace,monospace}.controls{display:flex;flex-wrap:wrap;gap:10px;align-items:center;padding:18px 0}.btn{background:var(--ink);color:white;border-radius:4px;padding:10px 16px;font-weight:700}.btn:hover{background:var(--green)}.btn.secondary{background:transparent;color:var(--ink);border:1px solid var(--ink)}.btn.live{background:var(--accent)}.grid{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(340px,.9fr);gap:20px}.panel{background:var(--card);border:1px solid var(--line);box-shadow:var(--shadow);border-radius:8px;padding:20px}.panel h2{font:700 23px Georgia,serif;margin:0 0 5px}.kicker{font:11px ui-monospace,monospace;letter-spacing:.12em;text-transform:uppercase;color:var(--muted)}.live-log{min-height:420px;max-height:650px;overflow:auto;margin-top:18px}.segment{border-top:1px solid var(--line);padding:15px 0;display:grid;grid-template-columns:100px 1fr;gap:15px}.segment:first-child{border-top:0}.stamp{color:var(--muted);font:12px ui-monospace,monospace}.speaker{font-size:11px;color:var(--green);text-transform:uppercase;letter-spacing:.1em}.low{color:var(--warn);background:#f8e9c9;padding:1px 4px;border-radius:3px}.hint{color:var(--muted);font-size:14px}.summary{display:grid;gap:12px;margin-top:18px}.note-card{border-top:1px solid var(--line);padding:14px 0}.note-card strong{font-family:Georgia,serif;font-size:18px}.note-card ul{padding-left:20px}.search{display:flex;gap:8px;margin:14px 0}.search input{flex:1;border:1px solid var(--line);border-radius:4px;background:white;padding:9px 11px}.results{display:grid;gap:8px}.result{padding:10px;border:1px solid var(--line);border-radius:4px}.result a{color:var(--green);font-weight:700;cursor:pointer}.exports{display:flex;gap:6px;flex-wrap:wrap;margin-top:10px}.exports a{color:var(--green);font:12px ui-monospace,monospace}.meter{height:5px;background:#e4e1d7;border-radius:4px;overflow:hidden;margin:14px 0}.meter i{display:block;height:100%;width:0;background:var(--accent);transition:width .1s}.empty{padding:45px 10px;text-align:center;color:var(--muted)}details{border-top:1px solid var(--line);padding:12px 0}summary{cursor:pointer;font-weight:700}@media(max-width:900px){.grid{grid-template-columns:1fr}.top{display:block}.top .pill{display:inline-block;margin-top:18px}.shell{padding:18px 15px}.segment{grid-template-columns:76px 1fr}}
</style></head><body><div class="shell">
<header class="top"><div><div class="mark">NT / 02 — HIGH-FIDELITY KNOWLEDGE CAPTURE</div><h1>Keep the signal.</h1><p class="subtitle">Live transcription that preserves reasoning, evidence, decisions, and the details worth finding again.</p></div><div class="grow"></div><span class="pill" id="model">local pipeline</span></header>
<section class="controls"><button class="btn" id="record">Start capture</button><button class="btn secondary" id="clear">Clear live view</button><span class="pill" id="status">idle</span><span class="pill" id="words">0 words</span><div class="grow"></div><span class="hint">Audio stays local unless an optional provider is configured.</span></section>
<div class="grid"><section class="panel"><div class="kicker">Live evidence ledger</div><h2>Transcript, not just a summary</h2><p class="hint">Every segment retains timestamps, words, confidence, language, and speaker metadata. Low-confidence regions are marked for review.</p><div class="meter"><i id="meter"></i></div><div id="live" class="live-log"><div class="empty">Press <b>Start capture</b>, allow microphone access, and speak.</div></div></section>
<section class="panel"><div class="kicker">Knowledge base</div><h2>Find what you already captured</h2><div class="search"><input id="query" placeholder="Search concepts, names, deadlines, URLs…"><button class="btn" id="search">Search</button></div><div id="results" class="results"><div class="empty">Saved notes, concepts, actions, questions, and timestamps appear here.</div></div><div id="selected" class="summary"></div></section></div>
</div><script>
const $=s=>document.querySelector(s);let ws,ctx,node,stream,running=false,segments=[],lines=[];
const stamp=s=>{s=Math.max(0,Math.floor(s));return [Math.floor(s/3600),Math.floor(s/60)%60,s%60].map(v=>String(v).padStart(2,'0')).join(':')};
function renderSegment(s,partial=false){const el=document.createElement('article');el.className='segment';const c=s.confidence??0;el.innerHTML=`<div><div class="stamp">${stamp(s.start)}–${stamp(s.end)}</div><div class="speaker">${s.speaker||'Unknown speaker'}</div></div><div>${partial?'<em>draft · </em>':''}${c<.65?'<span class="low">review</span> ':''}${escapeHtml(s.text)}<div class="hint">${s.language||'auto'} · ${Math.round(c*100)}% confidence</div></div>`;return el}
function escapeHtml(v){return String(v).replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]))}
function addSegment(s){if(!s.text)return;segments.push(s);const live=$('#live');if(live.querySelector('.empty'))live.innerHTML='';live.append(renderSegment(s));live.scrollTop=live.scrollHeight;lines.push(s.text);$('#words').textContent=lines.join(' ').trim().split(/\s+/).filter(Boolean).length+' words'}
async function capture(){
 $('#status').textContent='connecting';ws=new WebSocket((location.protocol==='https:'?'wss://':'ws://')+location.host+'/ws');ws.binaryType='arraybuffer';ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.t==='ready'){$('#model').textContent=m.model||'local pipeline'}else if(m.t==='level'){$('#meter').style.width=Math.round(m.v*100)+'%';$('#status').textContent=m.on?'speech':'listening'}else if(m.t==='partial'){$('#status').textContent='drafting'}else if(m.t==='segment'){addSegment(m)}else if(m.t==='note'){$('#status').textContent='saved · '+m.title}};await new Promise((ok,no)=>{ws.onopen=ok;ws.onerror=no});stream=await navigator.mediaDevices.getUserMedia({audio:{channelCount:1,echoCancellation:true,noiseSuppression:true,autoGainControl:true}});ctx=new AudioContext({sampleRate:16000});const worklet=`class C extends AudioWorkletProcessor{constructor(){super();this.b=new Float32Array(1024);this.i=0}process(x){const c=x[0][0];if(!c)return true;for(const v of c){this.b[this.i++]=v;if(this.i===1024){this.port.postMessage(this.b.slice());this.i=0}}return true}}registerProcessor('capture',C)`;await ctx.audioWorklet.addModule(URL.createObjectURL(new Blob([worklet],{type:'application/javascript'})));node=new AudioWorkletNode(ctx,'capture');node.port.onmessage=e=>{if(ws.readyState===1){const x=e.data,o=new Int16Array(x.length);for(let i=0;i<x.length;i++){const v=Math.max(-1,Math.min(1,x[i]));o[i]=v<0?v*32768:v*32767}ws.send(o.buffer)}};const gain=ctx.createGain();gain.gain.value=0;ctx.createMediaStreamSource(stream).connect(node);node.connect(gain).connect(ctx.destination);running=true;$('#record').textContent='Stop capture';$('#record').classList.add('live');$('#status').textContent='listening'}
function stop(){running=false;if(ws&&ws.readyState===1)ws.send(JSON.stringify({t:'flush'}));stream?.getTracks().forEach(t=>t.stop());ctx?.close();node=null;ctx=null;$('#record').textContent='Start capture';$('#record').classList.remove('live');$('#status').textContent='stopped'}
$('#record').onclick=()=>running?stop():capture().catch(e=>{$('#status').textContent='error: '+e.message;running=false});$('#clear').onclick=()=>{$('#live').innerHTML='<div class="empty">Live view cleared. Saved notes remain searchable.</div>';segments=[];lines=[];$('#words').textContent='0 words'});
async function search(){const q=encodeURIComponent($('#query').value);const data=await fetch('/api/notes?query='+q).then(r=>r.json());$('#results').innerHTML=data.length?data.map(n=>`<div class="result"><a onclick="openNote('${n.id}')">${escapeHtml(n.title)}</a><div class="hint">${n.source_type} · ${stamp(n.duration)} · ${n.created_at}</div></div>`).join(''):'<div class="empty">No matching evidence yet.</div>'}
async function openNote(id){const n=await fetch('/api/notes/'+id).then(r=>r.json());$('#selected').innerHTML=`<div class="note-card"><strong>${escapeHtml(n.title)}</strong><ul>${(n.executive_summary||[]).map(x=>'<li>'+escapeHtml(x)+'</li>').join('')}</ul><div class="exports">${['md','pdf','docx','json','html','anki'].map(x=>`<a href="/api/notes/${n.id}/export/${x}" target="_blank">export ${x}</a>`).join(' · ')}</div></div>`}
$('#search').onclick=search;$('#query').onkeydown=e=>{if(e.key==='Enter')search()};search();
</script></body></html>'''
